(function () {
    const containerId = 'custom-message-container';

    function createContainer() {
      let container = document.getElementById(containerId);
      if (!container) {
        container = document.createElement('div');
        container.id = containerId;
        container.className = 'custom-message-container';
        document.body.appendChild(container);
      }
      return container;
    }

    function showMessage(type, content, duration = 3, callback) {
      const container = createContainer();
      const message = document.createElement('div');
      message.className = `custom-message custom-message-${type}`;

      const success_icon = `<svg viewBox="64 64 896 896" focusable="false" data-icon="check-circle" width="1.2em" height="1.2em" fill="currentColor" aria-hidden="true"><path d="M699 353h-46.9c-10.2 0-19.9 4.9-25.9 13.3L469 584.3l-71.2-98.8c-6-8.3-15.6-13.3-25.9-13.3H325c-6.5 0-10.3 7.4-6.5 12.7l124.6 172.8a31.8 31.8 0 0051.7 0l210.6-292c3.9-5.3.1-12.7-6.4-12.7z"></path><path d="M512 64C264.6 64 64 264.6 64 512s200.6 448 448 448 448-200.6 448-448S759.4 64 512 64zm0 820c-205.4 0-372-166.6-372-372s166.6-372 372-372 372 166.6 372 372-166.6 372-372 372z"></path></svg>`;

      const failed_icon = `<svg fill-rule="evenodd" viewBox="64 64 896 896" focusable="false" data-icon="close-circle" width="1.2em" height="1.2em" fill="currentColor" aria-hidden="true"><path d="M512 64c247.4 0 448 200.6 448 448S759.4 960 512 960 64 759.4 64 512 264.6 64 512 64zm0 76c-205.4 0-372 166.6-372 372s166.6 372 372 372 372-166.6 372-372-166.6-372-372-372zm128.01 198.83c.03 0 .05.01.09.06l45.02 45.01a.2.2 0 01.05.09.12.12 0 010 .07c0 .02-.01.04-.05.08L557.25 512l127.87 127.86a.27.27 0 01.05.06v.02a.12.12 0 010 .07c0 .03-.01.05-.05.09l-45.02 45.02a.2.2 0 01-.09.05.12.12 0 01-.07 0c-.02 0-.04-.01-.08-.05L512 557.25 384.14 685.12c-.04.04-.06.05-.08.05a.12.12 0 01-.07 0c-.03 0-.05-.01-.09-.05l-45.02-45.02a.2.2 0 01-.05-.09.12.12 0 010-.07c0-.02.01-.04.06-.08L466.75 512 338.88 384.14a.27.27 0 01-.05-.06l-.01-.02a.12.12 0 010-.07c0-.03.01-.05.05-.09l45.02-45.02a.2.2 0 01.09-.05.12.12 0 01.07 0c.02 0 .04.01.08.06L512 466.75l127.86-127.86c.04-.05.06-.06.08-.06a.12.12 0 01.07 0z"></path></svg>`;

      if (type === 'success') {
        message.innerHTML =  `<span class="custom-message-content">${success_icon} ${content}</span>`;
      } else if (type === 'error') {
        message.innerHTML =  `<span class="custom-message-content">${failed_icon} ${content}</span>`;
      } else {  
        message.textContent = content;
      }

      container.appendChild(message);

      setTimeout(() => {
        message.style.opacity = '0';
        setTimeout(() => {
          if(message) container.removeChild(message);
          if(callback) {
            callback();
          }
        }, 300);
      }, duration * 1000);
    }

    // Expose globally
    window.CustomMessage = {
      success(content, duration, callback) { showMessage('success', content, duration, callback); },
      error(content, duration, callback)   { showMessage('error', content, duration, callback); },
      info(content, duration, callback)    { showMessage('info', content, duration, callback); },
      warning(content, duration, callback) { showMessage('warning', content, duration, callback); },
      loading(content, duration, callback) { showMessage('loading', content, duration, callback); },
      close() {
        const container = document.getElementById(containerId);
        if (container){
          container.innerHTML = '';
        }
      }
    };
  })();