export const simpleToolbarPartial = (showImageAnnotation = false) =>
  `
        <div class="toolbar righticon">
            <div id="toolbarContainer">
                <div id="toolbarViewer" class="toolbarHorizontalGroup">
                    <div id="toolbarViewerRight" class="toolbarHorizontalGroup">
                        <div id="editorModeSeparator" class="verticalToolbarSeparator"></div>

                        <div class="toolbarHorizontalGroup hiddenMediumView">` +
  // <button id="editButton" class="toolbarButton editbutton editButtonEventClass" type="button" tabindex="0" data-l10n-id="pdfjs-edit-button">
  //     <span data-l10n-id="pdfjs-edit-button-label"></span>
  // </button>
  `                     ${showImageAnnotation ? `
                            <button id="annotate-toggle" class="toolbarButton imageCommentButton" type="button" tabindex="0">
                               <svg height="1em" viewBox="0 0 1024 1024"><path d="M66.782609 772.541217h196.051478a58.835478 58.835478 0 0 1 58.768696 58.768696v117.359304l235.78713-165.442782c9.928348-6.989913 21.615304-10.685217 33.747478-10.685218H957.217391V89.043478H66.782609v683.475479zM313.61113 1022.886957a58.768696 58.768696 0 0 1-58.768695-58.768696v-124.794435H58.724174A58.813217 58.813217 0 0 1 0 780.55513V81.029565A58.835478 58.835478 0 0 1 58.768696 22.26087h906.462608A58.835478 58.835478 0 0 1 1024 81.029565v699.503305a58.835478 58.835478 0 0 1-58.768696 58.768695H593.697391L347.336348 1012.201739c-10.106435 7.101217-21.904696 10.685217-33.725218 10.685218z" fill="white"></path><path d="M761.878261 326.032696h-499.756522a33.391304 33.391304 0 0 1 0-66.782609h499.756522a33.391304 33.391304 0 1 1 0 66.782609M761.878261 567.652174h-499.756522a33.391304 33.391304 0 0 1 0-66.782609h499.756522a33.391304 33.391304 0 1 1 0 66.782609" fill="white"></path></svg>
                                <span>Annotate</span>
                            </button>
                        ` : ''}
                            <button id="downloadButton" class="toolbarButton downloadButtonClass downloadButtonEventClass" type="button" tabindex="0" data-l10n-id="pdfjs-save-button">
                                <span data-l10n-id="pdfjs-save-button-label"></span>
                            </button>
                        </div>

                    </div>
                </div>
            </div>
        </div>
`;