export function renderMainLayout() {
  // Use the main template for the viewer layout 
  this.container = document.getElementById('docViewerContainer');
  if (!this.container) {
    this.handleError("No container found with id 'docViewerContainer'");
    return;
  }
  this.container.innerHTML = renderMainTemplate(this.viewerOptions.design == 'ecourt', undefined, this.getScriptBasePath());
  // Initialize jQuery plugins now that the template is in the DOM
  if (typeof initDocViewerCommon === 'function') initDocViewerCommon();
}

