const headingWrap = (htmlString, headingStyle) => {
  headingStyle = headingStyle || 'h5';
  return `<${headingStyle}>${htmlString}</${headingStyle}>`;
}

const getFormData = (formElement, raw) => {
    var formData = new FormData(formElement);
    if(raw) return formData;
    var data = {};
    formData.forEach((value, key) => {
      if (data.hasOwnProperty(key)) {
        if (!Array.isArray(data[key])) {
          data[key] = [data[key]];  
        }
        data[key].push(value);
      } else {
        data[key] = value;
      }
    });
    return data;
}

