  /**
   * Initialize WebSocket document sharing feature
   * This is called after the viewer is fully loaded
   * Includes dependency checking and graceful degradation
   */
  async initializeDocumentSharing() {
    try {
      console.log('DocViewer: Attempting to initialize document sharing...');
      
      // Check if ecourt design (required for refer button UI)
      if (this.viewerOptions.design !== 'ecourt') {
        console.log('Document sharing requires ecourt design. Current design:', this.viewerOptions.design);
        return false;
      }

      // Dynamically import the integration module
      const { DocumentSharingIntegration } = await import('./document-sharing-integration.mjs');
      
      this.documentSharing = new DocumentSharingIntegration();
      
      // Check enableSocketFeature from data attribute
      const enableSocketFeature = this.container.dataset['enableSocketFeature'];
      const featureEnabled = enableSocketFeature ? JSON.parse(enableSocketFeature) : false;
      
      // Initialize with explicit enable check
      const initialized = await this.documentSharing.initialize({
        enableSocketFeature: featureEnabled
      });
      
      if (initialized) {
        console.log('Document sharing feature enabled and initialized');
        
        // Expose to window for debugging
        if (window.DocViewer) {
          window.DocViewer.documentSharing = this.documentSharing;
        }
        
        return true;
      } else {
        console.log('Document sharing feature disabled or initialization failed');
        this.documentSharing = null;
        return false;
      }
    } catch (error) {
      console.error('Failed to initialize document sharing:', error);
      console.error('Stack trace:', error.stack);
      
      // Graceful degradation - don't break the application
      console.warn('Viewer will continue without document sharing feature');
      this.documentSharing = null;
      
      return false;
    }
  }

  /**
   * Clean up document sharing on destroy
   */
  destroyDocumentSharing() {
    if (this.documentSharing) {
      try {
        this.documentSharing.destroy();
      } catch (error) {
        console.error('Error destroying document sharing:', error);
      }
      this.documentSharing = null;
    }
  }

  // document summary feature methods
  getSummaryDataFromContainer() {
    const summaryDataAttr = this.getData('documentSummary');
    try {
      return summaryDataAttr ? JSON.parse(summaryDataAttr) : {};
    } catch (e) {
      console.error('Failed to parse document summary data:', e);
      return {};
    }
  }

