  // to convert lines or path.lines to float32array ( as per pdf.js annotation data object structure)
  convertToFloat32Array(input) {
    if (Array.isArray(input)) {
      return input.map(item => this.toFloat32(item));
    } else if (input && typeof input === 'object') {
      return [this.toFloat32(input)];
    }
    return [];
  }

  // outline

  async reapplyAnnotationsForPage(savedData, pageIndex) {
    console.log('Attempting to reapply annotations:', { pageIndex, savedData });
    
    if (!savedData?.storage?.map) {
      console.warn('No annotation data to apply');
      return;
    }

    const pageView = PDFViewerApplication.pdfViewer._pages?.[pageIndex];
    if (!pageView) {
      console.warn('Page view not found', pageIndex);
      return;
    }

    // Ensure editor layer exists and is initialized
    await this.ensureEditorLayerReady(pageView);

    const editorLayer = pageView.annotationEditorLayer;
    if (!editorLayer) {
      console.warn('Editor layer not available');
      return;
    }

    // Enable editor mode and ensure proper initialization
    // editorLayer.setEditingState(true);
    //await editorLayer.enable();

    try {
      // Get annotations for this page
      const pageAnnotations = Object.values(savedData.storage.map).filter(ann => 
        ann.pageIndex === pageIndex || 
        (ann.pageNumber === pageIndex + 1)
      );

      console.log(`Found ${pageAnnotations.length} annotations for page ${pageIndex}`, pageAnnotations);

      let appliedCount = 0;
      
      // Process each annotation
      for (const annotation of pageAnnotations) {
        try {
          // Use the editor layer's deserialize to create a proper editor instance
          const editor = await editorLayer.deserialize(annotation);
          if (!editor) {
            console.warn('Failed to deserialize annotation:', annotation);
            continue;
          }

          // Add to the layer which handles DOM attachment and event binding
          editorLayer.add(editor);
          
          // Enable editing explicitly
          editor.enableEditing();
          
          // Update annotation storage
          PDFViewerApplication.pdfDocument.annotationStorage.setValue(
            editor.id,
            editor.serialize()
          );

          appliedCount++;
        } catch (err) {
          console.error('Failed to recreate annotation:', err, annotation);
        }
      }

      // Force render update with proper viewport
      editorLayer.render({ viewport: pageView.viewport });
      
      console.log(`Successfully applied ${appliedCount} annotations to page ${pageIndex}`);

      // Update pending annotations state
      if (this.annotationService._pendingAnnotations) {
        const remainingAnnotations = Object.entries(savedData.storage.map)
          .filter(([_, value]) => value.pageIndex !== pageIndex)
          .reduce((obj, [key, value]) => {
            obj[key] = value;
            return obj;
          }, {});

        this.annotationService._pendingAnnotations = Object.keys(remainingAnnotations).length > 0 
          ? { storage: { map: remainingAnnotations } }
          : null;
      }

    } catch (error) {
      console.error('Error reapplying annotations to page:', error);
    }
  }

