  showBackButton(){
    this.container.querySelector('#back-button').classList.remove('hidden');
    this.container.querySelector('#back-button').href = this.container.dataset['backUrl'] || '#';
  }

  isShowEditItemButton(){
    if(this.viewerOptions.showEditItemButton == null){
      const showEditItemButton = this.container.dataset['showEditItemButton'];
      if( showEditItemButton != undefined && showEditItemButton == 'true' && this.getItemEditLinkUrl() != null) {
        return true;
      }
      return false;
    }
    return this.viewerOptions.showEditItemButton || false;
  }

  skipFileUploadSizeCheck(){
    return this.container.dataset['skipFileUploadSizeCheck'] == "true";
  }

  enableDisableEditItemButton(enable){
    enable = enable || false;
    const editButtons = this.container.querySelectorAll('.editButtonEventClass');
    // console.log('edit buttons ', editButtons, 'enable:', enable);
    if(editButtons.length > 0){ 
      editButtons.forEach(button => {
        if(enable){
          if(!button._itemEditListenerAttached){
            button._itemEditListenerAttached = true;
            button.addEventListener('click', (e) => {
              e.preventDefault();
              const editLink = this.getItemEditLinkUrl();
              if(editLink) {
                window.location.href = editLink;
              } else {
                console.warn("No edit link available for this item.");
              }
            });
          }
        } else {
          button.style.display = 'none';
        }
      });
    }
  }

