  switchTo(idType){
    const viewerContainers = document.querySelectorAll('.viewerContainers');
    const videoViewer = document.getElementById('videoViewer');
    if( videoViewer) videoViewer.classList.remove('active');
    if (this.videoPlayer) this.videoPlayer.pause();
    viewerContainers.forEach(element => {
      if(element.className.includes('shareViewerContainer')) return; // skip share viewer container:
      element.style.display = 'none'
    });
    const mediaPartialContainer = this.container.querySelector('#mediaContainer');
    mediaPartialContainer.style.display = 'none';
    if(idType == 'videoViewer') {
      mediaPartialContainer.style.display = 'block';
    }
    // document.getElementById(idType).style.display = 'none';
    document.getElementById(idType).style.display = 'block';
  }

