  _applyPageSelectionControlMode() {
    const inputContainer = this.container?.querySelector('#pageNumberInputContainer');
    const selectContainer = this.container?.querySelector('#pageNumberSelectContainer');

    if (!inputContainer || !selectContainer) return;

    const useSelect = this.viewerOptions.pageSelectionOptionType === 'select';
    inputContainer.style.display = useSelect ? 'none' : '';
    selectContainer.style.display = useSelect ? '' : 'none';

    if (!useSelect) return;

    this._bindPageNumberSelectChange();
    this._populatePageNumberSelect();
  }

  _bindPageNumberSelectChange() {
    const pageNumberSelect = this.container?.querySelector('#pageNumberSelect');
    if (!pageNumberSelect) return;

    if (this._onPageNumberSelectChange) {
      pageNumberSelect.removeEventListener('change', this._onPageNumberSelectChange);
    }

    this._onPageNumberSelectChange = (event) => {
      const selectedPage = parseInt(event?.target?.value, 10);
      if (!Number.isInteger(selectedPage) || selectedPage < 1) return;
      if (!window.PDFViewerApplication?.pdfViewer) return;
      PDFViewerApplication.page = selectedPage;
    };

    pageNumberSelect.addEventListener('change', this._onPageNumberSelectChange);
  }

  _populatePageNumberSelect() {
    if (this.viewerOptions.pageSelectionOptionType !== 'select') return;

    const pageNumberSelect = this.container?.querySelector('#pageNumberSelect');
    const pagesCount = PDFViewerApplication?.pagesCount || PDFViewerApplication?.pdfDocument?.numPages || 0;
    if (!pageNumberSelect || !pagesCount) return;

    pageNumberSelect.innerHTML = '';
    for (let page = 1; page <= pagesCount; page++) {
      const option = document.createElement('option');
      option.value = String(page);
      option.textContent = String(page);
      pageNumberSelect.appendChild(option);
    }

    this._syncPageNumberSelect(PDFViewerApplication?.page || 1);
  }

  _syncPageNumberSelect(pageNumber) {
    if (this.viewerOptions.pageSelectionOptionType !== 'select') return;

    const pageNumberSelect = this.container?.querySelector('#pageNumberSelect');
    if (!pageNumberSelect) return;

    const nextValue = String(parseInt(pageNumber, 10) || 1);
    if (pageNumberSelect.value !== nextValue) {
      pageNumberSelect.value = nextValue;
    }
  }

  /* pdf viewer init */
  async showPdfViewer(blobUrl, fileuuid,fileUrl) {
    // console.log(' --------------------------------------------------------------------- ', fileuuid)
    try {
      
      this.switchTo('outerContainer');
      
      // For subsequent PDF loads, we need to reset the viewer application
      if (this.pdfViewer && PDFViewerApplication.pdfDocument) {
        await this.resetPdfViewer();
      }
      
      // Initialize PDF viewer options
      if (!this.pdfViewer) {
        PDFViewerApplicationOptions.setAll({
          workerSrc: this.getScriptBasePath() + '/doc-viewer/js/worker.js',
          // workerSrc: '/doc-viewer/js/worker.js',
          disablePreferences: true,
          defaultUrl: '',
          defaultZoomValue: this.viewerOptions.defaultZoomValue,
          ignoreDestinationZoom: this.viewerOptions.ignoreDestinationZoom,
          sidebarViewOnLoad: this.viewerOptions.sidebarViewOnLoad,
          enableScripting: this.viewerOptions.enableScripting,
          enableAnnotationEditor: true,
          enableSignatureEditor: this.viewerOptions.enableSignatureEditor,
          viewerCssTheme: this.viewerOptions.viewerCssTheme,
          cursorToolOnLoad: this.viewerOptions.cursorToolOnLoad,
          textLayerMode: this.viewerOptions.textLayerMode,
          viewOnLoad: this.viewerOptions.viewOnLoad,
          annotationMode: 3,  // ENABLE_STORAGE
        });
        // Wait for DOM to be ready
        await this.waitForDOMReady();
        
        // Initialize or re-initialize viewer
        const viewerContext = webViewerLoad();
        console.log('PDF Viewer initialized', viewerContext);
        this.pdfViewer = true;
        
        // Wait for viewer to be ready
        await PDFViewerApplication.initializedPromise;
        if (PDFViewerApplication.pdfLinkService) {
          PDFViewerApplication.pdfLinkService._ignoreDestinationZoom = !!this.viewerOptions.ignoreDestinationZoom;
        }
        await this._ensureAnnotExtLoaded(); // Ensure annotation-extension is loaded IMPORTANT -- do not remove or reorder -- make changes with caution
        this._bindAnnotationLifecycle();
      }

      // const caseuuid = this.getCurrentCaseUuid();
      // const currentFileuuid = fileuuid || this.getCurrentFileuuid() || '';
      // this.setData('anno-get', '/case/'+ caseuuid + '/annotations/load/' + currentFileuuid );
      // this.setData('anno-post', '/case/'+ caseuuid + '/annotations/save/' + currentFileuuid );
      // alert( '/case/'+ caseuuid + '/annotations/load/' + currentFileuuid )

      
      // Load the new PDF document
      await this.loadNewPdfDocument(blobUrl);

      if(this.viewerOptions.hideSignatureOption){
        this.container.querySelector('.CustomToolbar [title="Signature"]').style.display= 'none'
      }
      
      // // Re-enable annotation editor after loading new document
      // await this.reinitializeAnnotationEditor();
      
      // Initialize adapters and comment system
      await this.initializeViewerComponents();
      
      // Set default cursor tool
      PDFViewerApplication.pdfCursorTools.switchTool(0);

      // set default zoom level if specified in options
      if (this.viewerOptions.defaultZoomValue) {
        PDFViewerApplication.pdfViewer.currentScaleValue = this.viewerOptions.defaultZoomValue;
      }

      // Apply and sync page input/select mode for current document.
      this._applyPageSelectionControlMode();
      
      // Load comments after everything is initialized
      // await this.loadComments();
      
      console.log('PDF viewer setup completed successfully');
      
      // Initialize document sharing feature (if first time loading PDF)
      if (!this.documentSharing && this.viewerOptions.design === 'ecourt') {
        await this.initializeDocumentSharing();
      }
      
      // Notify judges if advocate has an active sharing session and switched to a new PDF
      if (this.documentSharing && fileUrl) {
        this.documentSharing.notifyDocumentChange(fileUrl, 1);
      }

      // Initialize findbar click-outside handler
      this.initFindbarClickOutside();

      // Initialize secondary toolbar click-outside handler
      this.initSecondaryToolbarClickOutside();

      // Initialize annotation toolbar click-outside handler
      this._initToolbarClickOutside();

      // check and show/hide the username from comments panel based on the option
      // this._showHideUsernameFromCommentsPanel();
    } catch (error) {
      console.error('Error setting up PDF viewer:', error);
      throw error;
    }
  }

