  // Reset PDF viewer for new document
  async resetPdfViewer() {
    console.log('Resetting PDF viewer for new document');
    
    try {
      // Close current document if exists
      if (PDFViewerApplication.pdfDocument) {

        // stop loading tasks if prsent 
        if (PDFViewerApplication.pdfLoadingTask) {
          PDFViewerApplication.pdfLoadingTask.destroy();
        }
        
        // clsose the document
        await PDFViewerApplication.close();
        
        // clear the URL to prevent auto-reload ( may not be needed - but just in case)
        PDFViewerApplication.url = '';
      }
      
      // Reset annotation editor
      if (PDFViewerApplication.annotationEditorUIManager) {
        PDFViewerApplication.annotationEditorUIManager.reset();
      }
      
      // Clear any existing annotations
      if (PDFViewerApplication.pdfViewer) {
        PDFViewerApplication.pdfViewer.cleanup();
      }

      //reset the annotation service state before loading new annotations
      this.annotationService.reset();
      
      // ------------------------------------------------------------------
      // clearing the viewer container to prevent old content from showing -- not clearing completely to prevent issues
      const viewerContainer = document.querySelector('#viewer');
      if (viewerContainer) {
        // scroll to top positon
        viewerContainer.scrollTop = 0;
      }
      // ------------------------------------------------------------------
      
      console.log('PDF viewer reset completed');
    } catch (error) {
      console.warn('Error during PDF viewer reset:', error);
    }
  }

  // Load new PDF document
  async loadNewPdfDocument(blobUrl) {

    // save older document annotations if any
    // await this.initSaveAnnotations(); // NOTE : NOT USED ANYMORE

    // console.log('Loading new PDF document:', blobUrl);
    
    try {
      // checking valid blob url
      if (!blobUrl || !blobUrl.startsWith('blob:')) {
        throw new Error('Invalid blob URL provided');
      }
      
      // clear any existing URL first - to prevent auto-fetch issues - may not be needed but just in case
      PDFViewerApplication.url = '';
      
      // Use PDFViewerApplication to open the new document
      const openParams = {
        url: blobUrl,
        originalUrl: blobUrl,
        //  disable download behavior -- that happens by default, in range mode it also 
        // disableAutoFetch: false,
        // disableStream: false,
        // disableRange: false
      };
      
      await PDFViewerApplication.open(openParams);
      
      // Wait for the document to be fully loaded
      if (PDFViewerApplication.pdfLoadingTask) {
        await PDFViewerApplication.pdfLoadingTask.promise;
      }
      
      console.log('New PDF document loaded successfully');
      this.currentPdf = PDFViewerApplication.pdfDocument;

      setTimeout(() => {
        if(this.bootstrapDropdowns.hasOwnProperty('js-pdf-export-case-files')){
          this.bootstrapDropdowns['js-pdf-export-case-files'].dispose();
        }
        const pdfDropdownEl = $('.js-pdf-export-case-files').get(0);
        if(pdfDropdownEl){
          const menu = new bootstrap.Dropdown(pdfDropdownEl);
          this.bootstrapDropdowns['js-pdf-export-case-files'] = menu; 
        }
        if(this.bootstrapDropdowns.hasOwnProperty('js-pdf-print-case-files')){
          this.bootstrapDropdowns['js-pdf-print-case-files'].dispose();
        }
        const pdfPrintDropdownEl = $('.js-pdf-print-case-files').get(0);
        if(pdfPrintDropdownEl){
          const menu2 = new bootstrap.Dropdown(pdfPrintDropdownEl);
          this.bootstrapDropdowns['js-pdf-print-case-files'] = menu2; 
        }
      }, 500);

      this._exportPdfEvents();
      this._printPdfEvents();
      this._checkPassJudgement();
      
      return this.currentPdf;
    } catch (error) {
      console.error('Error loading new PDF document:', error);
      throw new Error(`Failed to load PDF: ${error.message}`);
    }
  }

