  showImageViewer(blobUrl,blob){
    this.switchTo('imageContainer');

    const imageElem = this.container.querySelector('#imageViewer');
    if (!imageElem) return;

    // Set image source
    imageElem.src = blobUrl;

    // Destroy previous Annotorious/Viewer instances if any
    if (this.imgAnno && this.imgAnno.destroy) {
      try { this.imgAnno.destroy(); } catch (e) {}
      this.imgAnno = null;
    }
    if (this.imgViewer && this.imgViewer.destroy) {
      try { this.imgViewer.destroy(); } catch (e) {}
      this.imgViewer = null;
    }

    // --- Initialize Viewer.js on the SAME <img> (inline, no gallery UI) ---
    const _syncOverlay = () => syncOverlay();
    this.imgViewer = new Viewer(imageElem, {
      inline: true,
      navbar: false,
      title: false,
      toolbar: {
        zoomIn: 1, zoomOut: 1, oneToOne: 0, reset: 1,
        prev: 0, play: 0, next: 0, rotateLeft: 1, rotateRight: 1,
        flipHorizontal: 0, flipVertical: 0
      },
      viewed:  _syncOverlay,
      zoomed:  _syncOverlay,
      moved:   _syncOverlay,
      rotated: _syncOverlay
    });

    // --- Initialize Annotorious on the SAME <img> ---
    this.imgAnno = Annotorious.init({
      image: imageElem,
      widgets: ['COMMENT']
    });

    // === Helpers bound to THIS DOM STRUCTURE ===
    const wrapper = imageElem.parentElement; // the <div style="position: relative; display:inline-block;">
    function getActiveViewerImage() {
      // The transformed image that Viewer.js moves around
      const vc = wrapper.querySelector('.viewer-container .viewer-canvas img');
      return vc || imageElem; // fallback (before Viewer paints)
    }
    function getOverlayEl() {
      // Sibling SVG created by Annotorious in YOUR DOM
      return wrapper.querySelector('svg.a9s-annotationlayer');
    }

    // Ensure overlay is above viewer
    function bumpOverlayZIndex() {
      const overlay = getOverlayEl();
      const vc = wrapper.querySelector('.viewer-container');
      if (!overlay || !vc) return;
      const z = parseInt(getComputedStyle(vc).zIndex || '0', 10);
      overlay.style.position = 'absolute';
      overlay.style.zIndex = isNaN(z) ? '2' : String(z + 1);
      // Make wrapper the positioning context (it already is in your HTML)
      if (getComputedStyle(wrapper).position === 'static') {
        wrapper.style.position = 'relative';
      }
    }

    // The core: keep overlay aligned with the moving/zooming/rotating image
    const syncOverlay = () => {
      const overlay = getOverlayEl();
      const activeImg = getActiveViewerImage();
      if (!overlay || !activeImg) return;

      const s = getComputedStyle(activeImg);

      // Size overlay to current drawn image box
      overlay.style.width  = activeImg.clientWidth + 'px';
      overlay.style.height = activeImg.clientHeight + 'px';

      // Copy transform & origin (handles rotation/zoom when Viewer uses CSS transforms)
      overlay.style.transform = s.transform;
      overlay.style.transformOrigin = s.transformOrigin;

      // Place overlay at the same on-screen position
      const imgRect  = activeImg.getBoundingClientRect();
      const wrapRect = wrapper.getBoundingClientRect();
      overlay.style.left = (imgRect.left - wrapRect.left) + 'px';
      overlay.style.top  = (imgRect.top  - wrapRect.top)  + 'px';

      // Let clicks through unless in annotate mode
      overlay.style.pointerEvents = overlay.classList.contains('annotate-mode') ? 'auto' : 'none';
    };

    // Initial z-index/order once Viewer lays out
    requestAnimationFrame(() => {
      bumpOverlayZIndex();
      syncOverlay();
    });

    // Keep in sync on viewport/layout changes
    const ro = new ResizeObserver(() => requestAnimationFrame(syncOverlay));
    ro.observe(wrapper);
    window.addEventListener('resize', () => requestAnimationFrame(syncOverlay));

    // --- Annotate toggle (single button) ---
    const btnAnnotate = this.container.querySelector('#annotate-toggle');
    let annotating = false;

    const setAnnotateMode = (on) => {
      annotating = !!on;
      const overlay = getOverlayEl();
      if (overlay) {
        overlay.classList.toggle('annotate-mode', annotating);

        // Optional: block wheel while annotating so panning/zooming doesn't interfere
        const blockWheel = (e) => { e.preventDefault(); e.stopPropagation(); };
        if (annotating) overlay.addEventListener('wheel', blockWheel, { passive: false });
        else overlay.removeEventListener('wheel', blockWheel);
      }
      if (btnAnnotate) btnAnnotate.classList.toggle('active', annotating);
      syncOverlay();
    };

    if (btnAnnotate) {
      btnAnnotate.onclick = () => setAnnotateMode(!annotating);
    }

    // --- Load annotations if your dataset attributes are present ---
    const loadUrl = this.container.dataset['imgAnnoGet'];
    if (loadUrl) {
      fetch(loadUrl, { method: 'GET' })
        .then(r => r.ok ? r.json() : [])
        .then(data => {
          const arr = Array.isArray(data) ? data : (data?.annotations || []);
          this.imgAnno.clearAnnotations();
          if (arr?.length) this.imgAnno.setAnnotations(arr);
          requestAnimationFrame(syncOverlay);
        })
        .catch(() => {});
    }

    this.imgAnno.on('createAnnotation', (a) => {
      console.log('created', a);
      this.saveAnno();
    });
    this.imgAnno.on('updateAnnotation', (annotation, previous) => {
      if(this.isJsonEqual(annotation, previous)) return;
      console.log('updated', previous, 'with', annotation);
      this.saveAnno();
    });
    this.imgAnno.on('deleteAnnotation', (annotation) => {
      console.log('deleted', annotation);
      this.saveAnno();
    });

    // If you have a save endpoint in data-anno-post, wire it here or in your toolbar
    // Example:
    // const postUrl = this.container.dataset['annoPost'];
    // if (postUrl) { ... post this.imgAnno.getAnnotations() ... }
  }


  // to compare the json objects so that we do not save if there is no change
  isJsonEqual(a, b) {
    const sortKeys = obj => {
      if (Array.isArray(obj)) {
        return obj.map(sortKeys);
      } else if (obj && typeof obj === 'object') {
        return Object.keys(obj).sort().reduce((acc, key) => {
          acc[key] = sortKeys(obj[key]);
          return acc;
        }, {});
      }
      return obj;
    };

    return JSON.stringify(sortKeys(a)) === JSON.stringify(sortKeys(b));
  }


  async saveAnno() {
    const saveUrl = this.container.dataset.imgAnnoPost; // data-img-anno-post
    if (!saveUrl || !this.imgAnno) return false;

    const annos = this.imgAnno.getAnnotations();
    try {
      const r = await fetch(saveUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ annotations: annos })
        // credentials: 'include', // uncomment if your API needs cookies/CSRF
      });
      if (!r.ok) {
        const text = await r.text().catch(() => '');
        console.error('Failed to save annotations:', r.status, r.statusText, text);
        return false;
      }
      console.log('Annotations saved successfully');
      CustomMessage.success('Saved Successfully');
      return true;
    } catch (err) {
      console.error('Error saving annotations:', err);
      return false;
    }
  }



