  addEventListenerToAccordionItems(elementNode) {
    let filesSelector = elementNode.querySelectorAll(`.file-select`);    
    if (elementNode.classList.contains('file-select')) {
      filesSelector = [elementNode];
    }

    filesSelector.forEach(clickElem => {
      clickElem.addEventListener('click', async (e) => {
        e.stopPropagation();
        e.preventDefault();

        const fileElement = e.target.closest('.file-select');
        const selectedFileUrl = fileElement.dataset['url'];

        console.log('[Summary] File clicked:', fileElement.dataset.fileName, 
                    'isSummaryGenerated=', fileElement.dataset.isSummaryGenerated);

        if (selectedFileUrl) {
          // clear previous selection
          this.clearAccordionFileSelection('.file-select');
          fileElement.classList.add('selected');
          fileElement.querySelector('.file-toolbar')?.classList.remove('d-none');

          // render the newly selected file
          await this.renderFile(
            selectedFileUrl, 
            this.buildDownloadFilename(fileElement.dataset['fileName']), 
            fileElement.dataset['fileuuid'] 
          );

          // ✅ Update global summary button with selected file info
          this.setSummaryButtonState(fileElement);
        }
      });
    });
  }

setSummaryButtonState(fileElement) {
  console.log('----------------------- [Summary] fileElement:', fileElement);

  const globalSummaryBtn = document.getElementById('generateSummaryButton');
  if (!globalSummaryBtn) return;

  // -------------------------------
    // Hide if not ecourt design
    // -------------------------------
    if (this.viewerOptions.design !== 'ecourt') {
      console.log('[Summary] Not ecourt design → hiding summary button');
      globalSummaryBtn.style.display = 'none';
      globalSummaryBtn.disabled = true;
      return;
    }

    // -------------------------------
  const isSharingActive = referStopBtn && referStopBtn.style.display !== 'none';

  if (isSharingActive) {
    console.log('[Summary] Sharing active  hiding summary button');
    globalSummaryBtn.style.display = 'none';
    globalSummaryBtn.disabled = true;
    return;
  }

  const url = fileElement.dataset['url'] || '';
  const fileName = fileElement.dataset['fileName'] || '';
  const caseGuid = fileElement.dataset['caseGuid'] || '';
  const fileuuid = fileElement.dataset['fileuuid'] || '';

  // -------------------------------
  // Hide button for attached files
  // -------------------------------
  const isAttachedFile = url.startsWith('/files/case/');
  if (isAttachedFile) {
    console.log('[Summary] Attached file → hiding summary button');
    globalSummaryBtn.style.display = 'none';
    globalSummaryBtn.disabled = true;
    return;
  }

  // -------------------------------
  // Hide if missing dataset
  // -------------------------------
  if (!caseGuid || !fileName || !fileuuid) {
    console.warn('[Summary] Missing dataset → hiding summary button');
    globalSummaryBtn.style.display = 'none';
    globalSummaryBtn.disabled = true;
    return;
  }

  // -------------------------------
  // Show button for normal files
  // -------------------------------
  globalSummaryBtn.style.display = 'flex';
  globalSummaryBtn.disabled = false;

  // -------------------------------
  // Sync dataset
  // -------------------------------
  globalSummaryBtn.dataset.caseGuid = caseGuid;
  globalSummaryBtn.dataset.fileName = fileName;
  globalSummaryBtn.dataset.fileuuid = fileuuid;
  globalSummaryBtn.dataset.url = url;

  const isGenerated = String(fileElement.dataset['isSummaryGenerated']).toLowerCase() === 'true';
  globalSummaryBtn.dataset.isSummaryGenerated = isGenerated ? 'true' : 'false';

  // -------------------------------
  // Update button text + classes
  // -------------------------------
  const btnInner = globalSummaryBtn.querySelector('button span');
  if (isGenerated) {
    if (btnInner) btnInner.textContent = 'View Summary';
    globalSummaryBtn.querySelector('button')?.classList.add('js-summary-generated');
  } else {
    if (btnInner) btnInner.textContent = 'Generate Summary';
    globalSummaryBtn.querySelector('button')?.classList.remove('js-summary-generated');
  }

  // -------------------------------
  // Clear summary panel
  // -------------------------------
  const summaryPanel = document.getElementById('summaryPanel');
  if (summaryPanel) summaryPanel.textContent = '';

  // -------------------------------
  // Disable for unsupported file types
  // -------------------------------
  const ext = fileName.split('.').pop().toLowerCase();
  const supportedDocs = ['pdf', 'doc', 'docx', 'txt'];
  if (!supportedDocs.includes(ext)) {
    console.log('[Summary] Unsupported file type → hiding button');
    globalSummaryBtn.disabled = true;
    globalSummaryBtn.style.display = 'none';
  }

  // -------------------------------
  // Sync <li> datasetx`
  // -------------------------------
  fileElement.dataset.isSummaryGenerated = globalSummaryBtn.dataset.isSummaryGenerated;

  console.log('[Summary] Final button state:', {
    fileName,
    fileuuid,
    caseGuid,
    isGenerated
  });
}
