  //refresh notes from polling - adds new notes and updates existing ones
  refreshNotes(notes) {
    if (!notes || !notes.length || !this._notesContainer) return;
    
    const newNotes = [];
    const updatedNotes = [];
    const deletedNotes = [];
    
    // separate new notes, updated notes, and deleted notes
    notes.forEach(note => {
      // Handle deleted notes
      if (note.is_deleted) {
        const existingItem = this._notesContainer.querySelector(
          `.update-list__listsection--item[data-guid="${note.guid}"]`
        );
        if (existingItem) {
          deletedNotes.push(existingItem);
        }
        return;
      }
      
      const existingItem = this._notesContainer.querySelector(
        `.update-list__listsection--item[data-guid="${note.guid}"]`
      );
      
      if (existingItem) {
        if (!note.is_new) {
          updatedNotes.push({ note, element: existingItem });
        }
      } else {
        newNotes.push(note);
      }
    });
    
    // remove deleted notes from DOM
    deletedNotes.forEach(element => {
      element.remove();
    });
    
    // update existing notes content
    updatedNotes.forEach(({ note, element }) => {
      const contentElem = element.querySelector('.note-content .content');
      if (contentElem) {
        const escapedContent = note.content
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");
        contentElem.dataset.full = escapedContent;
        contentElem.textContent = note.content;
      }
    });
    
    // add new notes
    if (newNotes.length) {
      // sort notes by created_on desc (newest first) to prepend in correct order
      newNotes.sort((a, b) => {
        const ta = new Date(a.created_on || a.created_date || 0).getTime();
        const tb = new Date(b.created_on || b.created_date || 0).getTime();
        return tb - ta; // desc order
      });
      
      // add note to list
      const tempDiv = document.createElement('div');
      newNotes.forEach(note => {
        tempDiv.innerHTML = this._noteRenderHTML(note);
        const newNoteElem = tempDiv.firstElementChild;
        if (newNoteElem) {
          this._notesContainer.prepend(newNoteElem);
        }
      });
    }
    
    // update clamping and dropdowns
    this._noteInitClamping();
    this._noteInitDropdowns();
  }

  initUploadHandler() {
    const container = this.container;

    const uploadUrl = container.dataset.uploadUrl; 
    if (!uploadUrl) {
        console.warn("Upload URL missing from data-upload-url");
        return;
    }

    const fileInput = container.querySelector('#upload-files');
    const dropZone  = container.querySelector('#upload-container');

    if (!fileInput || !dropZone) {
        console.error("Upload input/drop zone missing in template");
        return;
    }

    // browse
    fileInput.addEventListener('change', (e) => {
        const files = e.target.files;
        if (files && files.length) {
            this.handlePdfUpload(files, uploadUrl);
        }
    });

    // drag highlight
    dropZone.addEventListener('dragover', (e) => {
        e.preventDefault();
        dropZone.classList.add('drag-over');
    });

    dropZone.addEventListener('dragleave', () => {
        dropZone.classList.remove('drag-over');
    });

    // drop upload
    dropZone.addEventListener('drop', (e) => {
        e.preventDefault();
        dropZone.classList.remove('drag-over');
        const files = e.dataTransfer.files;
        if (files && files.length) {
            this.handlePdfUpload(files, uploadUrl);
        }
    });
  }


  async handlePdfUpload(files, uploadUrl) {
    const pdfFiles = [...files].filter(f => f.type === "application/pdf");

    if (!pdfFiles.length) {
        CustomMessage.error("Only PDF file allowed");
        console.error("Only PDF files allowed");
        return;
    }

    for (const file of pdfFiles) {

        const fd = new FormData();
        // fd.append("pdf_file", file);
        fd.append("file", file);
        fd.append("case_guid", this.container.dataset.caseGuid);
        fd.append("category", 'attached_case_files');

        try {
            CustomMessage.loading("Uploading file…");

            const resp = await fetch(uploadUrl, {
                method: "POST",
                body: fd
            });

            CustomMessage.close();


            if (!resp.ok) {
              CustomMessage.error("Upload failed");
              console.error("Upload failed:", await resp.text());
              continue;
            }

            const data = await resp.json();

            if (!data || data.result != "success") {
                CustomMessage.error(data.message || "Upload failed");
                console.error("Upload error:", data);
                continue;
            }

            // Success and update case file list
            const fileData = [data.file[0]]
            const attachedFileContainer = this.container.querySelector('#accordion-category-attached_case_files');
            console.log('attachedFileContainer',attachedFileContainer);
            let newFileElem = null;
            const tempDiv = document.createElement('div');
            if(attachedFileContainer){
              tempDiv.innerHTML = renderEcourtAccordionFilePartial('attached_case_files', fileData,true);
              newFileElem = tempDiv.firstElementChild;
              attachedFileContainer.querySelector('.c-listcontainer__listitem').prepend(newFileElem);
            } else {
              const accordionMainParent = this.container.querySelector('#documents').querySelector('#accordionFileSelection');
              tempDiv.innerHTML = renderEcourtAccordionFilePartial('attached_case_files', fileData);
              newFileElem = tempDiv.firstElementChild;
              accordionMainParent.prepend(newFileElem);
            }

            // add event listener to the new file element
            if(newFileElem) this.addEventListenerToAccordionItems(newFileElem);

            // add file or accordion and open the accordion
            document.querySelector('button[data-bs-target="#accordion-category-attached_case_files"]').click();
            CustomMessage.success("File uploaded successfully");

            // IMPORTANT:
            // Do NOT modify DOM here.
            // Do NOT create accordion here.
            // Only call the placeholder handler.
            if( typeof this.onUploadSuccess === 'function'){
              this.onUploadSuccess(data.file);
            }

        } catch (err) {
            console.error("Upload network error:", err);
        }
    }
  }

