  async handleMediaUpload(files, uploadUrl, category) {
    console.log('handleMediaUpload ==== ',files, uploadUrl, category);

    // const mediaFiles = [...files].filter(f => f.type == category +"/");
    // const mediaFiles = [...files].filter(f => f.type.startsWith(category + "/"));
    // const mediaFiles = [...files].filter(f => f.type.startsWith(category + "/"));

    const SIZE_LIMITS = {
      image: 10 * 1024 * 1024,   // 10 MB
      audio: 50 * 1024 * 1024,   // 50 MB
      video: 250 * 1024 * 1024   // 250 MB
    };
    const maxSize = SIZE_LIMITS[category] || (10 * 1024 * 1024);

    const extAudio = /\.(flac|mp3|wav|m4a|ogg|aac|opus)$/i;
    const extVideo = /\.(mp4|m4v|mov|avi|mkv|webm|ogv)$/i;
    const extImage = /\.(jpe?g|png|gif|webp|bmp|tiff|svg)$/i;

    const mediaFiles = [...files].filter(f => {
      const t = (f.type || '').toLowerCase();
      const name = (f.name || '').toLowerCase();
      if (t && t.startsWith(category + '/')) return true;
      if (!t) {
        if (category === 'audio' && extAudio.test(name)) return true;
        if (category === 'video' && extVideo.test(name)) return true;
        if (category === 'image' && extImage.test(name)) return true;
      }
      console.error("Invalid file type for ", category, ":", f.name, f.type);
      return false;
    });


    if (!mediaFiles.length) {
        CustomMessage.error("Only "+category+" file allowed");
        console.error("Only "+category+" files allowed");
        return;
    }

    for (const file of mediaFiles) {
      // size check
      if (!this.skipFileUploadSizeCheck() && typeof file.size == "number" && file.size > maxSize) {
        const readableMax = (maxSize / (1024*1024)).toFixed(1) + " MB";
        CustomMessage.error(`File "${file.name}" exceeds the ${readableMax} limit for ${category}.`);
        console.error(`File "${file.name}" too large: ${file.size} > ${maxSize}`);
        continue; // skip this file
      }

      const fd = new FormData();
      fd.append("file", file);
      fd.append("case_guid", this.container.dataset.caseGuid);
      fd.append("category", 'media_' + category);

      for (const pair of fd.entries()) {
        console.log('FormData entry:', pair[0], pair[1]);
      }

      try {
          CustomMessage.loading("Uploading file…");

          const resp = await fetch(uploadUrl, {
              method: "POST",
              body: fd,
              credentials: "same-origin"
          });

          CustomMessage.close();


          if (!resp.ok) {
            CustomMessage.error("Upload failed");
            console.error("Upload failed:", await resp.text());
            continue;
          }

          const data = await resp.json();

          if (!data || data.status != "success") {
              CustomMessage.error(data.message || "Upload failed");
              console.error("Upload error:", data);
              continue;
          }

          // Success and update case file list
          // const fileData = [data.file[0]]
          const fileData = [data.media]
          const attachedFileContainer = this.container.querySelector('#accordion-category-attached_'+category+'_files');
          console.log('attachedFileContainer',attachedFileContainer);
          let newFileElem = null;
          const tempDiv = document.createElement('div');
          if(attachedFileContainer){
            // if accordion exists - add to its list
            tempDiv.innerHTML = renderEcourtAccordionFilePartial('attached_'+category+'_files', fileData, true, category, category +'Accordion');
            newFileElem = tempDiv.firstElementChild;
            attachedFileContainer.querySelector('.c-listcontainer__listitem').prepend(newFileElem);
          } else {
            // if accordion doesn't exist - create parent structure if needed
            const mediaSelectionContainer = this.container.querySelector('#'+category+'SelectionContainer');
            if (mediaSelectionContainer) {
              // check if the accordion parent exists
              let accordionMainParent = mediaSelectionContainer.querySelector('#'+category);
              if (!accordionMainParent) {
                // create the accordion parent container (same as renderMediaAccordion)
                accordionMainParent = document.createElement('div');
                accordionMainParent.className = "accordion fileaccordion";
                accordionMainParent.id = category;
                mediaSelectionContainer.appendChild(accordionMainParent);
              }
              // create new accordion with the file
              tempDiv.innerHTML = renderEcourtAccordionFilePartial('attached_'+category+'_files', fileData, false, category, category +'Accordion');
              newFileElem = tempDiv.firstElementChild;
              accordionMainParent.prepend(newFileElem);
            }
          }

          // add event listener to the new file element
          if(newFileElem) this.addEventListenerToAccordionItems(newFileElem);

          // add file or accordion and open the accordion
          const button = document.querySelector('button[data-bs-target="#accordion-category-attached_'+category+'_files"]');
          if (button) {
            (__dv$ || window.$)(button).click();
          }
          CustomMessage.success("File uploaded successfully");

          // IMPORTANT:
          // Do NOT modify DOM here.
          // Do NOT create accordion here.
          // Only call the placeholder handler.
          if( typeof this.onUploadSuccess === 'function'){
            this.onUploadSuccess(data.media);
          }

      } catch (err) {
          console.error("Upload network error:", err);
      }
    }
  }




