// modal template for document summary
export function renderSummaryModal(fileName, summaryContent) {
    return `
        <div class="modal fade document-summary-modal" id="documentSummaryModal" tabindex="-1"
             aria-labelledby="documentSummaryModalLabel" aria-hidden="true">
            <div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable">
                <div class="modal-content">

                    <div class="modal-header border-0 pb-0">
                        <div class="summary-header">
                            <div class="summary-badge">
                                <i class="far fa-file-alt"></i>
                                <span>AI GENERATED SUMMARY</span>
                            </div>
                            <h5 class="modal-title mt-2" id="documentSummaryModalLabel">
                                ${fileName}
                            </h5>
                        </div>
                        <button type="button" class="btn-close" data-bs-dismiss="modal"
                                aria-label="Close"></button>
                    </div>

                    <div class="modal-body pt-2">
                        <div class="summary-section-title">SUMMARY</div>

                        <div id="summaryContent" class="summary-content">
                            ${summaryContent}
                        </div>
                    </div>
                    
                  

                </div>
            </div>
        </div>
    `;
}
