// renders the judge list dropdown grouped by status
// shows: accepted, rejected, pending, available, disconnected

export const renderJudgeList = (judgesData = {}) => {
    const { accepted = [], rejected = [], pending = [], available = [], disconnected = [] } = judgesData;
    
    const renderSection = (status, judges, headerText) => {
        if (!judges || judges.length === 0) return '';
        
        const showButton = (judge) => {
            if (status === 'accepted') return false;
            
            if (status === 'disconnected') return false;
            
            if (status === 'available') return true;
            
            if (status === 'rejected') return true;
            
            // show resend for pending judges who never confirmed receipt
            if (status === 'pending') {
                return !judge.requestReceived;
            }
            
            return false;
        };
        
        const getButtonLabel = () => {
            if (status === 'available') return 'Send';
            return 'Resend';
        };
        
        return `
            <div class="selectStatus__section selectStatus__section--${status}">
                <div class="selectStatus__header">${headerText}</div>
                <ul class="selectStatus__list">
                    ${judges.map(judge => `
                        <li class="judge-list-item" data-judge-id="${judge.id || ''}" data-judge-name="${judge.name || ''}" data-request-received="${judge.requestReceived || false}">
                            <span class="judge-name">${judge.name || 'Unknown Judge'}</span>
                            ${showButton(judge) ? `
                                <button type="button" 
                                        class="btn-send-request" 
                                        data-judge-id="${judge.id}" 
                                        data-judge-name="${judge.name}"
                                        title="${getButtonLabel()} request to ${judge.name}">
                                        <svg xmlns="http://www.w3.org/2000/svg" width="19" height="19" viewBox="0 0 19 19" fill="none">
                                            <g clip-path="url(#clip0_2653_959)">
                                            <path d="M17.3474 9.98577C17.2993 10.286 17.2271 10.5781 17.1329 10.8602C16.9277 11.4745 16.6178 12.0408 16.2244 12.5381C15.2094 13.8212 13.6387 14.6445 11.8757 14.6445H6.33398C3.72028 14.6445 1.58398 12.5381 1.58398 9.89453C1.58398 7.26232 3.72 5.14453 6.33398 5.14453H17.4173" stroke="#174377" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                            <path d="M15.041 2.76953L17.416 5.14453L15.041 7.51953" stroke="#174377" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                            <path d="M9.5 7.51953V12.2695" stroke="#174377" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                            <path d="M9.5 7.51953L8.3125 8.70703L7.71875 9.30078" stroke="#174377" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                            </g>
                                            <defs>
                                            <clipPath id="clip0_2653_959">
                                            <rect width="19" height="19" fill="white"/>
                                            </clipPath>
                                            </defs>
                                        </svg>
                                </button>
                            ` : ''}
                        </li>
                    `).join('')}
                </ul>
            </div>
        `;
    };
    
    return `
        <div class="selectStatus" id="judgeStatusList" style="display:none;position:absolute;">
            ${renderSection('accepted', accepted, 'Accepted')}
            ${renderSection('pending', pending, 'Pending')}
            ${renderSection('available', available, 'Available')}
            ${renderSection('rejected', rejected, 'Rejected')}
            ${renderSection('disconnected', disconnected, 'Disconnected')}
        </div>
    `;
};

// update judge list dynamically
export const updateJudgeList = (judgesData = {}) => {
    const container = document.getElementById('judgeStatusList');
    if (!container) return;
    
    const newContent = renderJudgeList(judgesData);
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = newContent;
    const newList = tempDiv.firstElementChild;
    
    if (newList) {
        const isVisible = container.style.display === 'block' || 
                         (container.style.display !== 'none' && 
                          window.getComputedStyle(container).display !== 'none');
        
        container.parentNode.replaceChild(newList, container);
        
        if (isVisible) {
            newList.style.display = 'block';
        }
        
        attachSendButtonHandlers(newList);
    }
};

function attachSendButtonHandlers(container) {
    const buttons = container.querySelectorAll('.btn-send-request');
    
    buttons.forEach(button => {
        button.addEventListener('click', (e) => {
            e.stopPropagation();
            
            const judgeId = button.dataset.judgeId;
            const judgeName = button.dataset.judgeName;
            
            // dispatch custom event for the UI layer to handle
            const event = new CustomEvent('sendRequestToJudge', {
                detail: { judgeId, judgeName },
                bubbles: true
            });
            button.dispatchEvent(event);
        });
    });
}
