export function renderAccordionFilePartial(category, filesData, summaryButton) {
    
    // highlight master file - master file will be the one selected by default & master accordion also
    const categoryLowerCase = category.toLowerCase(); 
    const showAccordionClass = categoryLowerCase == 'other' ? 'accordion-collapse collapse show' : 'accordion-collapse collapse'; 
    const showAccordionButtonClass = categoryLowerCase == 'other' ? 'accordion-button' : 'accordion-button collapsed'; 
    const fileList = filesData.map(item => {
        let selectedClass = (item.hasOwnProperty('isMaster') && item.isMaster == 1) ? 'selected' : '';
        return `<li class="file-select c-listcontainer__listitem--item ${selectedClass}" data-url="${item.url}" data-fileuuid="${item?.fileuuid}" data-file-name="${item?.filename}" >${item.name}${summaryButton(item)}</li>`
    }).join('');

    const accordionTemplate = 
    `<div class="accordion-item">
        <h2 class="accordion-header">
            <button class="${showAccordionButtonClass}" type="button" data-bs-toggle="collapse" data-bs-target="#accordion-category-${category}" aria-expanded="true" aria-controls="accordion-category-${category}">${category}</button>
        </h2>
        <div id="accordion-category-${category}" class=" ${showAccordionClass} " data-bs-parent="#accordionFileSelection">
            <div class="accordion-body">
                <div class="c-listcontainer list4 witharrow">
                    <ul class="c-listcontainer__listitem">
                        ${fileList}
                    </ul>
                </div>
            </div>
        </div>
    </div>`;
    return accordionTemplate;
}

// builds summary button HTML for file items
export function renderSummaryButton(item) {
    if (!item.hasOwnProperty('isMaster') && !item.hasOwnProperty('isJudgement')) {
        return '';
    }

    const summaryType = item.hasOwnProperty('isMaster') ? 'master' : 'judgement';
    const buttonText = item.isSummaryGenerated ? 'View Summary' : 'Generate Summary';
    const generatedClass = item.isSummaryGenerated ? 'js-summary-generated' : '';
    
    return `<a href="#" class="js-summary-button ${generatedClass}" data-name="${item?.name}" data-summary-type="${summaryType}" data-file-name="${item?.filename}" data-fileuuid="${item?.fileuuid}">${buttonText}</a>`;
}