export function renderEcourtAccordionFilePartial(
  category,
  filesData,
  summaryButton = null,
  onlyFileList = false,
  defaultOpenCategory = 'case_files',
  accordionCategoryId = 'accordionFileSelection'
) {

  // 🛡️ BACKWARD COMPATIBILITY FIX
  // Handles old calls like: (category, filesData, true)
  if (typeof summaryButton === 'boolean') {
    onlyFileList = summaryButton;
    summaryButton = null;
  }

  const categoryLowerCase = category.toLowerCase();

  const showAccordionClass =
    categoryLowerCase === defaultOpenCategory
      ? 'accordion-collapse collapse show'
      : 'accordion-collapse collapse';

  const showAccordionButtonClass =
    categoryLowerCase === defaultOpenCategory
      ? 'accordion-button'
      : 'accordion-button collapsed';

  const urlParams = new URLSearchParams(window.location.search);
  const caseGuid = urlParams.get("case_guid");

  const fileList = filesData.map(item => {
    const nameLower = item.name?.toLowerCase() || "";
    const isMasterFile = item.isMaster == 1 || nameLower === "master";
    const selectedClass = isMasterFile ? 'selected' : '';

    const itemHtml = `
      <a href="javascript:;" class="link">
        <div class="icon">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="23" viewBox="0 0 24 30" fill="none">
            <path d="M6 16.5H15M6 22.5H18M13.5 1.5H1.5V28.5H22.5V10.5M13.5 1.5H15L22.5 9V10.5M13.5 1.5V7.5C13.5 9 15 10.5 16.5 10.5H22.5"
                  stroke-width="2.25"
                  stroke-linecap="round"
                  stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="content">
          <div class="documentname">${item.name}</div>
          ${
            item.created_date
              ? `<div class="uploaddatetime">
                   ${item.created_date}
                   <span class="time">${item.created_time || ''}</span>
                 </div>`
              : ``
          }
        </div>
      </a>
    `;

    return `
      <li class="file-select c-listcontainer__listitem--item ${selectedClass}"
          data-url="${item.url}"
          data-fileuuid="${item.fileuuid || ''}"
          data-case-guid="${caseGuid}"
          data-file-name="${item.filename || item.name}"
          data-is-summary-generated="${item.isSummaryGenerated ? 'true' : 'false'}">
        ${itemHtml}
        ${
          typeof summaryButton === 'function'
            ? summaryButton(item, 'file', caseGuid)
            : ''
        }
      </li>
    `;
  }).join('');

  if (onlyFileList) return fileList;

  const accordionHTML = `
    <div class="accordion-item">
      <h2 class="accordion-header">
        <button class="${showAccordionButtonClass}"
                type="button"
                data-bs-toggle="collapse"
                data-bs-target="#accordion-category-${category}"
                aria-expanded="true"
                aria-controls="accordion-category-${category}">
          ${category.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}
        </button>
      </h2>
      <div id="accordion-category-${category}"
           class="${showAccordionClass}"
           data-bs-parent="#${accordionCategoryId}">
        <div class="accordion-body">
          <div class="c-listcontainer list2 list4_witharrow_older_class">
            <ul class="c-listcontainer__listitem">
              ${fileList}
            </ul>
          </div>
        </div>
      </div>
    </div>`;

  // -----------------------
  // SAME FLOW (just safer)
  // -----------------------
  setTimeout(() => {
    const lis = document.querySelectorAll(`#${accordionCategoryId} .file-select`);

    lis.forEach(li => {

      // جلوگیری duplicate listener (important for uploads)
      if (li.dataset.listenerAttached) return;
      li.dataset.listenerAttached = "true";

      li.addEventListener('click', () => {

        lis.forEach(l => l.classList.remove('selected'));
        li.classList.add('selected');

        const btn = document.getElementById('generateSummaryButton');
        if (btn) {
          const { fileName, fileuuid, caseGuid, isSummaryGenerated } = li.dataset;

          btn.dataset.fileName = fileName;
          btn.dataset.fileuuid = fileuuid;
          btn.dataset.caseGuid = caseGuid;
          btn.dataset.isSummaryGenerated = isSummaryGenerated;

          if (isSummaryGenerated === "true") {
            btn.textContent = "View Summary";
            btn.classList.add('btn-view');
            btn.classList.remove('btn-generate');
          } else {
            btn.textContent = "Generate Summary";
            btn.classList.add('btn-generate');
            btn.classList.remove('btn-view');
          }

          btn.style.display = 'block';
          btn.disabled = false;
        }
      });
    });
  }, 0);

  return accordionHTML;
}