


// ─── Doc-viewer common initializations ────────────────────────────────────────
// These are called by initDocViewerCommon() AFTER the viewer template has been
// rendered into the DOM, so selectors actually find elements.

function adjustChosenDirection() {
  $('.chzn-select').each(function () {
    const $select = $(this);
    const $chosen = $select.next('.chosen-container');
    if ($chosen.length == 0) return;

    const rect = $chosen[0].getBoundingClientRect();
    const spaceBelow = window.innerHeight - rect.bottom;
    const spaceAbove = rect.top;

    if (spaceBelow < 210 && spaceAbove > spaceBelow) {
      $chosen.addClass('chosen-up');
    } else {
      $chosen.removeClass('chosen-up');
    }
  });
}

// Called once after doc-viewer's HTML template has been injected into the DOM.
function initDocViewerCommon() {
  // Chosen selects
  $(".chzn-select").chosen();
  adjustChosenDirection();

  // SumoSelect multi-selects
  $('.testSelAll').SumoSelect({ okCancelInMulti: true, selectAll: true, search: true });

  // Bootstrap 5 tooltips (no jQuery plugin — use native constructor)
  document.querySelectorAll('[data-toggle="tooltip"], [data-bs-toggle="tooltip"]').forEach(function(el) {
    new bootstrap.Tooltip(el);
  });

  // Recheck chosen direction on resize/scroll (register once)
  $(window).off('resize scroll', adjustChosenDirection)
           .on('resize scroll', adjustChosenDirection);
}

window.initDocViewerCommon = initDocViewerCommon;




  


