  /**
   * Load saved annotations from the backend
   */
  async loadAnnotations(fileId, pageNumber) {
    pageNumber = pageNumber || 0;
    if(this.annotationOptions.onLoad && typeof this.annotationOptions.onLoad == 'function'  && !this.isAnnotationsFetched) {
      try {
        const response = this.annotationOptions.onLoad(fileId,pageNumber);
        this._pendingAnnotations = response.annotations;
        return response;
      } catch (error) {
      }
      this.isAnnotationsFetched = true;
      return false;
    }
  }

