  // called by viewer-app.js -- getUserAnnotations
  async extractAnnotations(pdfDocument, fileId) {
    if (!pdfDocument) return null;

    const storage = pdfDocument.annotationStorage;
    const storageData = storage?.serializable || {};
    const transfer = storageData?.transfer || [];

    // Convert transfer[] entries
    const transferData = [];
    for (const item of transfer) {
      if (item) {
        transferData.push({
          width: item.width,
          height: item.height,
          base64: await this.imageBitmapToBase64(item),
        });
      } else {
        transferData.push(null);
      }
    }

    // Convert any inline bitmap in real storage.map
    let mapObj = {};
    if (storageData?.map && typeof storageData.map.entries === "function") {
      for (const [k, v] of storageData.map.entries()) {
        const ann = { ...v };
        if (ann?.bitmap && ann.bitmap.width && ann.bitmap.height) {
          ann.bitmap = {
            width: ann.bitmap.width,
            height: ann.bitmap.height,
            base64: await this.imageBitmapToBase64(ann.bitmap),
          };
        }
        mapObj[k] = ann;
      }
    }

    return {
      fileId,
      storage: { ...storageData, ...(mapObj ? { map: mapObj } : {}) },
      transfer: transferData,
    };
  }

  /**
   * Updating the annotation storage index
   */
  updateAnnotationStorageIndex(map) {
    // Find highest annotation ID to prevent conflicts
    let maxId = -1;
    Object.keys(map).forEach(key => {
      const match = key.match(/pdfjs_internal_editor_(\d+)/);
      if (match) {
        maxId = Math.max(maxId, parseInt(match[1]));
      }
    });

    // Update PDF.js's internal ID counter
    if (maxId >= 0) {
      // Access the internal editor manager to update the ID counter
      PDFViewerApplication.pdfViewer.annotationEditorUIManager.setId(maxId + 1)
    }
  }

  /**
   * Convert an ImageBitmap to base64 string
   * @private
   */
  async imageBitmapToBase64(imgBitmap) {
    const canvas = document.createElement('canvas');
    canvas.width = imgBitmap.width || 1;
    canvas.height = imgBitmap.height || 1;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(imgBitmap, 0, 0);
    return canvas.toDataURL('image/png');
  }

