export const renderReferBtnContent = (state, referringCountText) => {
    // state: 1 - initial state, 2 - request initiated, 3 - sharing active, 4 - sharing rejected
    
    let content = '';
    state = state || 1;
    
    if (state == 1) {
        content = `
            <div class="default">
                <span class="default__icon">
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="20" viewBox="0 0 18 20" fill="none">
                        <path d="M5.74967 3.83398L8.62467 0.958984M8.62467 0.958984L11.4997 3.83398M8.62467 0.958984V10.5423M3.83323 7.66732C2.94018 7.66732 2.49365 7.66732 2.14142 7.81318C1.67178 8.00772 1.29844 8.38108 1.1039 8.85076C0.958008 9.20295 0.958008 9.64925 0.958008 10.5423V15.1423C0.958008 16.2157 0.958008 16.7521 1.16691 17.1621C1.35067 17.5227 1.64367 17.8165 2.00432 18.0003C2.41391 18.209 2.95037 18.209 4.02171 18.209H13.2281C14.2994 18.209 14.8352 18.209 15.2447 18.0003C15.6054 17.8165 15.8989 17.5227 16.0826 17.1621C16.2913 16.7525 16.2913 16.2166 16.2913 15.1453V10.5423C16.2913 9.64925 16.2912 9.20295 16.1454 8.85076C15.9508 8.38108 15.5778 8.00772 15.1082 7.81318C14.7559 7.66732 14.3094 7.66732 13.4163 7.66732" stroke="white" stroke-width="1.91667" stroke-linecap="round" stroke-linejoin="round"/>
                    </svg>
                </span>
                <span class="default__label">Refer to Judge</span>
            </div>`;
    } else if (state == 2) {
        referringCountText = referringCountText || 'Referring to Judge';
        content = `<div class="prog">${referringCountText}</div>`;
    } else if (state == 3) {
        content = `
            <div class="status js-share-active">
                <div class="status__icon"></div>
                <div class="status__label">Referring</div>
            </div>`;
    } else if (state == 4) {
        content = `
            <div class="rejected">
                <div class="rejected__icon"></div>
                <div class="rejected__label">Rejected</div>
            </div>`;
    }
    
    return content;
}

export const renderReferBtn = (state, referringCountText) => {
    const content = renderReferBtnContent(state, referringCountText);
    
    state = parseInt(state) || 1;

    let classReButton = {1: '', 2: 'prog', 3: 'status', 4: 'rejected'}[state];
    
    let referBtnTemplate = `
        <button class="referBtn ${classReButton}" data-status="${state}" id="referBtn">
            ${content}
        </button>
        `;
    
    return referBtnTemplate;
}
