import { renderPDFPartial } from './pdf.js';
import { renderDocxPartial } from './docx.js';
import { renderMediaPartial } from './media.js';
import { renderTextImagePartial } from './text-image.js';
import { renderExcelPartial } from './excel.js';
import { renderExcelViewerPartial } from './excel-viewer.js';
import { renderDownloadFilePartial } from './download.js';
import { renderPptxPartial } from './pptx.js';
import { renderViewJudgementModal } from './_view-judgement';
import { renderPassJudgementModal } from './_pass-judgement';
import { renderShareCommentModal } from './_share-comment';
import { renderSharePDFPartial } from './share-pdf.js';
import { renderReferBtn } from './_refer-btn.js';
import { renderJudgeList } from './_judge-list.js';

export const renderMainTemplate = (ecourt, fullView, imgBase = '') => `
<div class="container-fluid" id="pdfNoPrintContainer">
  <div class="row">
    <div class="col-12">
      <div class="c-boxContainer d1">
        <div class="c-boxContainer__content">
          <div class="c-boxContainer__content--leftsection" id="docViewerContainerLeftSection" ${fullView ? 'style="display:none"' : ''}>
            <div class="doctypewrap">
              <div class="docnamewrap">
                <a id="back-button" href="javascript:;" class="backbt hidden"><i class="fas fa-arrow-left"></i></a>
                <div class="hw d1 bluecolor">
                  <h2 id="viewer-heading" class="hw__title"></h2>
                  ${ecourt ? `` : 
                  `
                  <h3 id="viewer-sub-heading" class="hw__subtitle"></h3>
                  `
                  }
                </div>
              </div>
              ${ecourt ? `
              <div class="iconwrap">
                <div class="iconsection leftside">
                  <a href="javascript:;" style="display:none;" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="Tooltip on top" class="icon"><img id="iconsection-leftside-download-icon-img" dist-orig-src="${imgBase}/doc-viewer/images/pdfjs/download-icon.svg" class="u-img"/></a>
                  <a href="javascript:;" style="display:none;" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="Tooltip on top" class="icon"><img id="iconsection-leftside-mail-icon-img" dist-orig-src="${imgBase}/doc-viewer/images/pdfjs/mail-icon.svg" class="u-img"/></a>
                </div>
                <a class="passjuge js-pass-judgement d-none" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="Pass Judgement" href="javascript:;"><img id="iconsection-leftside-pass-judgement-icon-img" class="u-img"/> <span>Pass Judgment</span></a>
                <a class="passjuge js-view-judgement d-none" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="View Judgement" href="javascript:;"><img id="iconsection-leftside-view-judgement-icon-img" class="u-img"/> <span>View Judgment</span></a>
                
                <div class="referWrapper" style="display:none;">
                  ${renderReferBtn()}
                  ${renderJudgeList()}
                </div>

              </div>
              ` 
              : 
              `
              <div class="iconsection">
                <a data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="Tooltip on top" class="icon editbutton editButtonEventClass" style="display:none;"><i class="fas fa-pen"></i></a>
                <a data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="Tooltip on top" class="icon" style="display:none;"><i class="fas fa-envelope"></i></a>
                <a data-bs-toggle="tooltip" style="display:none" data-bs-placement="top" data-bs-title="Tooltip on top" class="icon"><i class="fas fa-download"></i></a>
              </div>
              `
              }
              <div class="tabview ${ecourt ? 'd5' : 'd1'} ">
                <ul class="nav nav-pills" id="pills-tab" role="tablist">
                  ${ecourt 
                  ? 
                  `
                  <li class="nav-item" role="presentation">
                    <button class="nav-link" id="pills-home-tab" data-bs-toggle="pill" data-bs-target="#information" type="button" role="tab" aria-controls="information" aria-selected="true">Information</button>
                  </li>
                  <li class="nav-item" role="presentation">
                    <button class="nav-link active" id="pills-profile-tab" data-bs-toggle="pill" data-bs-target="#documents" type="button" role="tab" aria-controls="documents" aria-selected="false">Documents</button>
                  </li>
                  <li class="nav-item" role="presentation">
                    <button class="nav-link" id="pills-profile-tab" data-bs-toggle="pill" data-bs-target="#media" type="button" role="tab" aria-controls="media" aria-selected="false">Media</button>
                  </li>
                  <li class="nav-item" role="presentation">
                    <button class="nav-link" id="pills-profile-tab" data-bs-toggle="pill" data-bs-target="#updates" type="button" role="tab" aria-controls="updates" aria-selected="false">Updates</button>
                  </li>
                  `
                  : 
                  `
                  <li class="nav-item" role="presentation">
                    <button class="nav-link active" id="pills-home-tab" data-bs-toggle="pill" data-bs-target="#documenttype" type="button" role="tab" aria-controls="documenttype" aria-selected="true">Document Type</button>
                  </li>
                  <li class="nav-item" role="presentation">
                    <button class="nav-link" id="pills-profile-tab" data-bs-toggle="pill" data-bs-target="#metadata" type="button" role="tab" aria-controls="metadata" aria-selected="false">Metadata</button>
                  </li>
                  `
                  }
                </ul>
              </div>
            </div>
            <div class="tab-content mt-3" id="pills-tabContent">
              ${ecourt 
              ? 
              `
              <div class="tab-pane fade" id="information" role="tabpanel" aria-labelledby="information">
                <div style="height:100%; overflow-y:auto;"> 
                  <div id="metadataContainer" class="c-listcontainer list12">
                  </div>
                </div>
              </div>

              <div class="tab-pane fade show active" id="documents" role="tabpanel" aria-labelledby="documents">
                
                <form class="drapdropform">
                  <label class="drapdropform__container" id="upload-container">
                    <span class="icon"><img id="upload-icon-img" class="u-img" /></span>
                      Drop files to attach, or <strong>browse</strong>
                    <input class="drapdropform__file" id="upload-files" accept="application/pdf" type="file" />
                  </label>
                </form>

                <div class="alldouctmentfilelist">
                  
                  <div class="c-listcontainer documentlist" style="height:max-content;">
                      
                    <ul class="c-listcontainer__listitem d-none" >
                      <li class="c-listcontainer__listitem--item">
                        <a href="javascript:;" class="link">
                          <div class="icon">
                                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="23" viewBox="0 0 24 30" fill="none">
                                  <path d="M6 16.5H15M6 22.5H18M13.5 1.5H1.5V28.5H22.5V10.5M13.5 1.5H15L22.5 9V10.5M13.5 1.5V7.5C13.5 9 15 10.5 16.5 10.5H22.5" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round"/>
                                </svg>
                          </div>
                          <div class="content">
                            <div class="documentname">Order</div>
                            <div class="uploaddatetime"> - 01-09-25 <span class="time">9:00AM</span></div>
                          </div>
                        </a>
                        <div class="action">
                          <a href="javascript:;" class="actionlink">
                            <img src="${imgBase}/doc-viewer/images/pdfjs/action-link.svg" class="u-img" />
                          </a>
                        </div>
                      </li>
                    </ul>

                  </div>

                  <div class="c-listcontainer documentlist v2" id="fileSelectionContainer" >
                  </div>
                  
                </div> 

              </div>

              <div class="tab-pane fade" id="media" role="tabpanel" aria-labelledby="media">
                <div class="tabview6container">
                  <div class="tabview d6">
                    <ul class="nav nav-pills" id="pills-tab2" role="tablist">
                      <li class="nav-item" role="presentation">
                        <button class="nav-link active" id="pills-tab2" data-bs-toggle="pill" data-bs-target="#audio" type="button"
                          role="tab" aria-controls="information" aria-selected="true"><svg xmlns="http://www.w3.org/2000/svg"
                            width="18" height="21" viewBox="0 0 18 21" fill="none">
                            <path fill-rule="evenodd" clip-rule="evenodd"
                              d="M16.5861 0.0564526C16.3979 0.0500139 16.2094 0.0573778 16.0222 0.0784852L6.10622 1.62765C4.98809 1.74056 4.86706 2.26384 4.87669 2.91517V16.0245C4.30869 15.65 3.69942 15.3842 2.88936 15.3842C1.84413 15.3842 1.22111 15.7836 0.844274 16.3123C0.467439 16.8397 0.342285 17.5035 0.342285 18.0171C0.342285 18.6368 0.555459 19.2964 1.01344 19.8004C1.47279 20.3044 2.17695 20.6583 3.18918 20.6583C4.33344 20.6583 5.13662 20.3388 5.59185 19.7136C5.94943 19.222 6.14885 18.5638 6.22037 17.7541C6.23 17.6549 6.23412 17.553 6.241 17.4498C6.2465 17.3671 6.24513 17.3093 6.2465 17.2129H6.252V6.60563C6.28226 5.75186 7.05519 5.62655 7.05519 5.62655L15.1063 4.36795C15.8778 4.1311 15.8792 5.08813 15.8792 5.08813V14.6475C15.3112 14.2729 14.7019 14.0072 13.8919 14.0072C12.8466 14.0072 12.2236 14.4065 11.8468 14.9353C11.4699 15.4627 11.3448 16.1264 11.3448 16.6401C11.3448 17.2597 11.558 17.9193 12.0159 18.4233C12.4753 18.9273 13.1795 19.2812 14.1917 19.2812C15.3359 19.2812 16.1391 18.9618 16.5944 18.3366C16.9519 17.845 17.1514 17.1868 17.2229 16.3771C17.2325 16.2779 17.2366 16.176 17.2435 16.0727C17.249 15.9901 17.2476 15.9323 17.249 15.8359H17.2545V1.28339C17.271 0.338745 17.062 0.0895015 16.5861 0.0564526Z"
                              fill="orange" />
                          </svg> <span>Audio</span></button>
                      </li>
                      <li class="nav-item" role="presentation">
                        <button class="nav-link" id="pills-tab2" data-bs-toggle="pill" data-bs-target="#video" type="button"
                          role="tab" aria-controls="documents" aria-selected="false"><svg xmlns="http://www.w3.org/2000/svg"
                            width="22" height="22" viewBox="0 0 22 22" fill="none">
                            <path fill-rule="evenodd" clip-rule="evenodd"
                              d="M6.6665 9.33772V12.6623C6.6665 14.9446 9.08223 15.8255 10.6325 15.0305L13.8744 13.3683C15.8195 12.3709 15.8194 9.62903 13.8744 8.63172L10.6325 6.96944C9.08223 6.17453 6.6665 7.05536 6.6665 9.33772ZM8.83317 12.6623C8.83317 13.0463 9.28015 13.2891 9.64394 13.1025L12.8858 11.4403C13.2601 11.2484 13.2601 10.7516 12.8858 10.5597L9.64394 8.89746C9.28015 8.71093 8.83317 8.95368 8.83317 9.33772V12.6623Z"
                              fill="#7C7C7C" />
                            <path fill-rule="evenodd" clip-rule="evenodd"
                              d="M5.58317 0.166748C2.59163 0.166748 0.166504 2.59188 0.166504 5.58341V16.4167C0.166504 19.4083 2.59163 21.8334 5.58317 21.8334H16.4165C19.408 21.8334 21.8332 19.4083 21.8332 16.4167V5.58341C21.8332 2.59188 19.408 0.166748 16.4165 0.166748H5.58317ZM2.33317 5.58341C2.33317 3.78849 3.78825 2.33341 5.58317 2.33341H16.4165C18.2115 2.33341 19.6665 3.78849 19.6665 5.58341V16.4167C19.6665 18.2117 18.2115 19.6667 16.4165 19.6667H5.58317C3.78825 19.6667 2.33317 18.2117 2.33317 16.4167V5.58341Z"
                              fill="#7C7C7C" />
                          </svg> <span>Video</span></button>
                      </li>
                      <li class="nav-item" role="presentation">
                        <button class="nav-link" id="pills-tab2" data-bs-toggle="pill" data-bs-target="#image" type="button"
                          role="tab" aria-controls="image" aria-selected="false"><svg xmlns="http://www.w3.org/2000/svg" width="22"
                            height="22" viewBox="0 0 22 22" fill="none">
                            <path fill-rule="evenodd" clip-rule="evenodd"
                              d="M6.6665 9.33772V12.6623C6.6665 14.9446 9.08223 15.8255 10.6325 15.0305L13.8744 13.3683C15.8195 12.3709 15.8194 9.62903 13.8744 8.63172L10.6325 6.96944C9.08223 6.17453 6.6665 7.05536 6.6665 9.33772ZM8.83317 12.6623C8.83317 13.0463 9.28015 13.2891 9.64394 13.1025L12.8858 11.4403C13.2601 11.2484 13.2601 10.7516 12.8858 10.5597L9.64394 8.89746C9.28015 8.71093 8.83317 8.95368 8.83317 9.33772V12.6623Z"
                              fill="#7C7C7C" />
                            <path fill-rule="evenodd" clip-rule="evenodd"
                              d="M5.58317 0.166748C2.59163 0.166748 0.166504 2.59188 0.166504 5.58341V16.4167C0.166504 19.4083 2.59163 21.8334 5.58317 21.8334H16.4165C19.408 21.8334 21.8332 19.4083 21.8332 16.4167V5.58341C21.8332 2.59188 19.408 0.166748 16.4165 0.166748H5.58317ZM2.33317 5.58341C2.33317 3.78849 3.78825 2.33341 5.58317 2.33341H16.4165C18.2115 2.33341 19.6665 3.78849 19.6665 5.58341V16.4167C19.6665 18.2117 18.2115 19.6667 16.4165 19.6667H5.58317C3.78825 19.6667 2.33317 18.2117 2.33317 16.4167V5.58341Z"
                              fill="#7C7C7C" />
                          </svg> <span>Image</span></button>
                      </li>
                    </ul>
                  </div>
                </div>
                
                <div class="tab-content mt-3" id="pills-tabContent2">
                  
                    <div class="tab-pane fade active show" id="audio" role="tabpanel" aria-labelledby="audio">
                     
                      <form class="drapdropform">
                        <label class="drapdropform__container" id="upload-audio-container">
                          <span class="icon"><img id="upload-icon-img" class="u-img" /></span>
                          Drop files to attach, or <strong>browse</strong>
                          <input class="drapdropform__file" id="upload-audio-files" accept="audio/*" type="file" />
                        </label>
                      </form>
                      <div style="height:calc(100% - 130px); overflow-y:auto;">
                        <div class="c-listcontainer documentlist v2" id="audioSelectionContainer">
                        </div>
                      </div> 
                    </div>

                    <div class="tab-pane fade" id="video" role="tabpanel" aria-labelledby="video">

                      <form class="drapdropform">
                        <label class="drapdropform__container" id="upload-video-container">
                          <span class="icon"><img id="upload-icon-img" class="u-img" /></span>
                          Drop files to attach, or <strong>browse</strong>
                          <input class="drapdropform__file" id="upload-video-files" accept="video/*" type="file" />
                        </label>
                      </form>
                      <div style="height:calc(100% - 130px); overflow-y:auto;">
                        <div class="c-listcontainer documentlist v2" id="videoSelectionContainer">
                        </div>
                      </div> 
                    </div>

                    <div class="tab-pane fade" id="image" role="tabpanel" aria-labelledby="image">

                      <form class="drapdropform">
                        <label class="drapdropform__container" id="upload-image-container">
                          <span class="icon"><img id="upload-icon-img" class="u-img" /></span>
                          Drop files to attach, or <strong>browse</strong>
                          <input class="drapdropform__file" id="upload-image-files" accept="image/*" type="file" />
                        </label>
                      </form>
                      <div style="height:calc(100% - 130px); overflow-y:auto;">
                          <div class="c-listcontainer documentlist v2" id="imageSelectionContainer">
                          </div>
                      </div>
                    </div>

                </div>

              </div>

              <div class="tab-pane fade" id="updates" role="tabpanel" aria-labelledby="updates">
                <div class="d-flex justify-content-center">
                  <a class="js-add-note u-button default radius-size6 size-30 size-90 mb-3 " data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="Add Update" href="javascript:;">
                    <span>Publish Case Update</span>
                  </a>
                </div>
                <div style="height:calc(100% - 45px); overflow-y:auto;">
                  <div class="update-list d1">
                    <div class="update-list__listsection">
                      <div class="update-list__listsection--item">
                        <div class="note">
                          <div class="icon">
                            <svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 21 21"
                              fill="none">
                              <path d="M17.3906 2.29688H3.60938V18.7031H17.3906V2.29688Z" stroke="black" stroke-width="1.96875"
                                stroke-linecap="round" stroke-linejoin="round" />
                              <path d="M7.54688 10.1719H13.4531M7.54688 14.1094H10.8281M7.54688 6.23438H13.4531" stroke="black"
                                stroke-width="1.96875" stroke-linecap="round" stroke-linejoin="round" />
                            </svg>
                          </div>
                          <div class="head">Note <span>21/80</span></div>

                        </div>
                        <div class="content">
                          Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt
                          ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut
                          aliquip ex ea commodo consequat. 
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
              ` 
              :
              `
              <div class="tab-pane fade show active" id="documenttype" role="tabpanel" aria-labelledby="documenttype-tab">
                <div style="height:100%; overflow-y:auto;"> 
                    <div id="fileSelectionContainer" class="c-form c-form-xs u-fieldRadius8 u-fieldShadow u-fieldBorderClr1 u-fieldHeight48 ">
                      
                    </div> 
                </div>
              </div>
              <div class="tab-pane fade" id="metadata" role="tabpanel" aria-labelledby="metadata-tab">
                <div style="height:100%; overflow-y:auto;"> 
                  <div id="metadataContainer" class="c-listcontainer list3 rowview"> <!--witharrow class add if u can use arrow in label-->
                  </div>
                </div>
              </div>
              `
              }
            </div>
          </div>
          <div class="c-boxContainer__content--rightsection" id="fullViewerContainer">
            ${renderDownloadFilePartial()}
            ${renderPDFPartial()}
            ${renderDocxPartial()}
            ${renderPptxPartial()}
            <div id="mediaContainer">
              ${renderMediaPartial()}
            </div>
            ${renderTextImagePartial()}
            ${renderExcelPartial()}
            ${renderExcelViewerPartial()}
          </div>
          <div class="c-boxContainer__content--rightsection width50" id="shareSectionContainer" style="display:none;">
            ${renderSharePDFPartial()}
          </div>
        </div>
      </div>
    </div>
  </div>
  ${renderViewJudgementModal()}
  ${renderPassJudgementModal()}
  ${renderShareCommentModal()}
</div>
<div id="printContainer"></div>`;
